  function getMarketCap(symbol, price) {
    const numPrice = Number(price) || 0;
    if (numPrice <= 0) return 0;

    const base = getBaseAsset(symbol);
    const cleanBase = base.startsWith('1000') ? base.slice(4) : base;

    // RULE: Market Cap is strictly Price * Circulating Supply
    const supply = getCirculatingSupply(symbol);
    if (supply > 0) {
      const effectiveSupply = base.startsWith('1000') ? (supply / 1000.0) : supply;
      return numPrice * effectiveSupply;
    }

    // Live market cap fallback from API
    if (liveMarketCaps[cleanBase] && liveMarketCaps[cleanBase] > 0) {
      return liveMarketCaps[cleanBase];
    }
    if (liveMarketCaps[base] && liveMarketCaps[base] > 0) {
      return liveMarketCaps[base];
    }

    // Registry fallback
    if (COIN_REGISTRY[cleanBase]) {
      return COIN_REGISTRY[cleanBase][0];
    }

    return numPrice * 1000000000;
  }

  function getCoinName(symbol) {
    const base = getBaseAsset(symbol);
    if (COIN_REGISTRY[base] && COIN_REGISTRY[base][1]) {
      return COIN_REGISTRY[base][1];
    }
    if (base.startsWith('1000') && COIN_REGISTRY[base.slice(4)]) {
      return COIN_REGISTRY[base.slice(4)][1];
    }
    return base;
  }

